// frontend/src/components/Logo.jsx
import React from 'react';

// Vector crest — crisp at every size, no raster pixelation.
export const Crest = ({ className = '', style }) => (
  <svg viewBox="0 0 100 64" className={`logo-crest ${className}`} style={style} role="img" aria-label="Pillar 5 Group">
    <rect x="35" y="4" width="5.5" height="9" rx="1" fill="var(--navy)" />
    <rect x="42" y="2" width="5.5" height="11" rx="1" fill="var(--navy)" />
    <rect x="52.5" y="2" width="5.5" height="11" rx="1" fill="var(--navy)" />
    <rect x="59.5" y="4" width="5.5" height="9" rx="1" fill="var(--navy)" />
    <path d="M33 12 H67 V32 C67 44 59 52 50 56 C49.4 56.3 48.6 56.3 48 56 C41 52 33 44 33 32 V12 Z" fill="var(--navy)" />
    <rect x="37" y="18" width="4.2" height="24" rx="1.4" fill="var(--cream)" />
    <rect x="43.8" y="18" width="4.2" height="24" rx="1.4" fill="var(--cream)" />
    <rect x="52" y="18" width="4.2" height="24" rx="1.4" fill="var(--cream)" />
    <rect x="58.8" y="18" width="4.2" height="24" rx="1.4" fill="var(--cream)" />
    <path d="M33 28 C18 24 4 20 0 8 C-1 4 0 2 2 3 C16 8 28 12 35 22 C37 25 36 29 33 28 Z" fill="var(--gold)" />
    <path d="M31 33 C15 31 0 30 -6 20 C-8 16 -7 14 -5 15 C10 18 24 20 33 27 C36 29 35 33 31 33 Z" fill="var(--gold-light)" />
    <path d="M67 28 C82 24 96 20 100 8 C101 4 100 2 98 3 C84 8 72 12 65 22 C63 25 64 29 67 28 Z" fill="var(--gold)" />
    <path d="M69 33 C85 31 100 30 106 20 C108 16 107 14 105 15 C90 18 76 20 67 27 C64 29 65 33 69 33 Z" fill="var(--gold-light)" />
  </svg>
);

// variant "mark" = crest only (header/sidebar/auth badges)
// variant "full" = crest + wordmark lockup (hero / large brand moments)
export default function Logo({ variant = 'mark', className = '', style }) {
  if (variant === 'full') {
    return (
      <div className={`logo-lockup ${className}`} style={style}>
        <Crest className="logo-lockup-crest" />
        <div className="logo-lockup-word">
          PILLAR<span>5</span>
        </div>
        <div className="logo-lockup-tag">Above Average</div>
      </div>
    );
  }
  return <Crest className={className} style={style} />;
}
